/*
 * A040556  Continued fraction for sqrt(581).
 * https://oeis.org/A040556
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy, less
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 87, u32 n <= 87, u64 n <= 87, u128 n <= 87,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Continued fraction terms for sqrt(581).
 * a(0)=24, subsequent terms generated by the standard continued fraction
 * algorithm for square roots. */

#include <stddef.h>
#include <stdbool.h>

static void compute_period(seq_t *period, size_t *len) {
    const seq_t D = 581;           /* The square root argument   */
    const seq_t a0 = 24;           /* floor(sqrt(581))          */
    seq_t m = 0;
    seq_t d = 1;
    seq_t a = a0;
    size_t cnt = 0;

    while (1) {
        seq_t m_next = d * a - m;
        seq_t d_next = (D - m_next * m_next) / d;
        seq_t a_next = (a0 + m_next) / d_next;

        period[cnt++] = a_next;
        m = m_next;
        d = d_next;
        a = a_next;

        if (a_next == 2 * a0)     /* Term 48 marks period end   */
            break;
    }
    *len = cnt;
}

seq_t a(idx_t n) {
    /* Periodic part excluding the initial a0. */
    static seq_t period[64];
    static size_t period_len = 0;
    static bool initialized = false;

    if (!initialized) {
        compute_period(period, &period_len);
        initialized = true;
    }

    if (n == 0)
        return 24;                 /* a0 */

    /* Wrap around the periodic part. */
    size_t idx = (size_t)((n - 1) % period_len);
    return period[idx];
}
